import { Locator, Page, expect } from '@playwright/test';
import BasePage from '../Framework/src/pages/base.page';
import { HTMLSubStepLogger } from '../Framework/src/utils/htmlSubStepLogger';

export class WaiverPage extends BasePage {
  constructor(page: Page, subStepLogger?: HTMLSubStepLogger) {
    super(page, subStepLogger);
  }

  // ==================== Locators ====================

  // --- Guest Details page: Waiver section ---

  get waiverSection(): Locator {
    return this.page.getByTestId('waiver-section').or(this.page.getByText(/waiver/i).locator('..').first());
  }

  get waiverStatusIndicator(): Locator {
    return this.waiverSection.getByText(/Sent|Pending Signature|Signed/i);
  }

  get sendWaiverButton(): Locator {
    return this.page.getByRole('button', { name: 'Send Waiver' });
  }

  get signedDocumentControl(): Locator {
    return this.waiverSection.getByRole('link', { name: /view|download/i }).or(
      this.waiverSection.getByRole('button', { name: /view|download/i }),
    );
  }

  get successToast(): Locator {
    return this.page.getByRole('status').or(this.page.getByText(/waiver (sent|resent)/i));
  }

  // --- Ranch Wizard: Initial Settings step — Docuseal Template ---

  get docusealTemplateDropdown(): Locator {
    return this.page.getByLabel(/docuseal template/i);
  }

  get docusealTemplateOptions(): Locator {
    return this.page.getByRole('listbox').getByRole('option');
  }

  getDocusealTemplateOption(templateName: string): Locator {
    return this.page.getByRole('option', { name: templateName });
  }

  get saveRanchSettingsButton(): Locator {
    return this.page.getByRole('button', { name: /save/i });
  }

  // ==================== Validations ====================

  async assertWaiverSectionVisible(): Promise<void> {
    await expect(this.waiverSection).toBeVisible();
    await expect(this.sendWaiverButton).toBeVisible();
  }

  async assertWaiverStatus(expectedStatus: 'Sent' | 'Pending Signature' | 'Signed'): Promise<void> {
    await expect(this.waiverStatusIndicator).toContainText(expectedStatus);
  }

  async assertSendWaiverButtonEnabled(): Promise<void> {
    await expect(this.sendWaiverButton).toBeVisible();
    await expect(this.sendWaiverButton).toBeEnabled();
  }

  async assertSignedDocumentControlVisible(): Promise<void> {
    await expect(this.signedDocumentControl).toBeVisible();
    const accessibleName = await this.signedDocumentControl.textContent();
    expect(accessibleName?.trim().toLowerCase()).not.toBe('click here');
  }

  async assertSuccessToastVisible(): Promise<void> {
    await expect(this.successToast).toBeVisible();
  }

  async assertDocusealTemplateDropdownVisible(): Promise<void> {
    await expect(this.docusealTemplateDropdown).toBeVisible();
  }

  async assertDocusealTemplateSelected(templateName: string): Promise<void> {
    await expect(this.docusealTemplateDropdown).toHaveText(new RegExp(templateName));
  }

  async assertNoErrorState(): Promise<void> {
    await expect(this.page.getByRole('alert')).toBeHidden();
  }

  // ==================== Actions ====================

  async clickSendWaiver(): Promise<void> {
    await this.logInfo('Clicking Send Waiver');
    await this.withHeal(this.sendWaiverButton, (l) => l.click(), 'Send Waiver Button');
  }

  async clickSendWaiverRapidly(times: number): Promise<void> {
    for (let i = 0; i < times; i += 1) {
      await this.withHeal(this.sendWaiverButton, (l) => l.click({ force: true }), 'Send Waiver Button (Rapid Click)');
    }
    await this.logInfo(`Clicked Send Waiver ${times} times in rapid succession`);
  }

  async openDocusealTemplateDropdown(): Promise<void> {
    await this.withHeal(this.docusealTemplateDropdown, (l) => l.click(), 'Docuseal Template Dropdown');
  }

  async selectDocusealTemplate(templateName: string): Promise<void> {
    await this.openDocusealTemplateDropdown();
    await this.withHeal(this.getDocusealTemplateOption(templateName), (l) => l.click(), `Docuseal Template Option: ${templateName}`);
  }

  async saveRanchSettings(): Promise<void> {
    await this.withHeal(this.saveRanchSettingsButton, (l) => l.click(), 'Save Ranch Settings Button');
    await this.logSuccess('Ranch Docuseal template configuration saved');
  }

  async configureDocusealTemplate(templateName: string): Promise<void> {
    await this.selectDocusealTemplate(templateName);
    await this.saveRanchSettings();
  }

  async openSignedDocument(): Promise<void> {
    await this.withHeal(this.signedDocumentControl, (l) => l.click(), 'Signed Document View/Download Control');
  }
}
